/*
 * Pasa la salida de SQL Server a los nombres de columna de Postgres.
 *
 * NO incluye `fecha_creacion`, y es lo más importante de este flujo. El tablero
 * decide a qué mes pertenece un caso mirando esa fecha, así que reescribirla
 * puede sacar el caso del mes que se está mirando: alguien abre agosto, aprieta
 * Actualizar, y agosto queda con menos casos que antes de actualizarlo. La
 * fecha de alta no cambia nunca, así que no hay nada que ganar reescribiéndola
 * y sí algo que perder.
 *
 * Las fechas se formatean con getters UTC, igual que en el refresco diario:
 * mezclar `toISOString()` con la hora local del servidor hace que cerca de
 * medianoche las dos mitades se contradigan.
 */
const fecha = (v) => (v ? new Date(v).toISOString().slice(0, 10) : null);
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};

return $input.all().map(({ json: r }) => ({
  json: {
    id: Number(r.Id),
    fecha_programado: fecha(r.FechaProgramado),
    estado: texto(r.Estado),
    repartidor: texto(r.Repartidor),
    tienda: texto(r.Tienda),
    destino: texto(r.Destino),
    poligono: texto(r.Poligono),
    visitas: Number.isFinite(Number(r.Visitas)) ? Number(r.Visitas) : null,
  },
})).filter((i) => Number.isFinite(i.json.id) && i.json.id > 0);
